import { useState } from 'react';
import SwipeRow from '../../../.upstream/src/ts-default/Micro/SwipeRow/SwipeRow';
import { DemoPanel } from '../../shared/demo-support';
import styles from '../../shared/micro-demos.module.css';
import {componentClasses} from '../../shared/class-names';
const cn=(names:string)=>componentClasses(styles,names);


export default function SwipeRowDemo() {
  const [message, setMessage] = useState('向左滑动条目，展开操作。');
  const [open, setOpen] = useState(/*__AW_STATE_state.open__*/);
  const [removed, setRemoved] = useState(false);
  const [revision, setRevision] = useState(0);
  return <DemoPanel title="Swipe Row · 行滑动操作"><div className={cn("aw-micro-stack")}>
    <div className={cn("aw-micro-wide")}>{removed ? <p className={cn("aw-micro-hint")}>本地演示行已移除。</p> : <SwipeRow key={revision}  open={open} onOpenChange={setOpen}        onAction={action => { setMessage(`已选择：${action.label}`); if (action.dismiss) setRemoved(true); }} onCommit={action => { setRemoved(true); setMessage(`滑动已确认：${action.label}`); }} /*__AW_PROPS_t0__*/ ><div style={{ padding: '16px 20px' }}><strong>技能配置草稿</strong><p style={{ margin: '4px 0 0', fontSize: 13 }}>仅在本地示例中归档或移除</p></div></SwipeRow>}</div>
    <div className={cn("aw-micro-controls")}><button className={styles['aw-micro-action']}  onClick={() => setOpen(value => !value)} disabled={removed} /*__AW_PROPS_t1__*/ >{open ? '关闭行操作' : '展开行操作'}</button><button className={styles['aw-micro-action']}  onClick={() => { setOpen(false); setRemoved(false); setRevision(value => value + 1); setMessage('示例行已恢复。'); }} /*__AW_PROPS_t2__*/ >恢复示例行</button></div>
    <p className={cn("aw-micro-status")} role="status" aria-live="polite">{message}</p>
  </div></DemoPanel>;
}
